<?php /** 赛事维护列表；负责人王乐之（2411302），AI辅助开发。 */ use yii\helpers\Html;$this->title='赛事维护'; ?><h1>赛事数据维护</h1><div class="actions"><?php foreach($types as $name):?><?= Html::a($name,['index','type'=>$name],['class'=>'button secondary']) ?><?php endforeach ?></div><p><?= Html::a('新增记录',['edit','type'=>$type],['class'=>'button']) ?></p><table><tr><th>ID</th><th>摘要</th><th>操作</th></tr><?php foreach($rows as $row):?><tr><td><?= $row->id ?></td><td><?= Html::encode($row->name??$row->source_key??$row->match_number??$row->type??$row->player_id??$row->id) ?></td><td><?= Html::a('编辑',['edit','type'=>$type,'id'=>$row->id]) ?> <?= Html::beginForm(['delete','type'=>$type,'id'=>$row->id],'post') ?><button onclick="return confirm('确定删除？')">删除</button><?= Html::endForm() ?></td></tr><?php endforeach ?></table><?= yii\widgets\LinkPager::widget(['pagination'=>$pages]) ?>
